    public String checkFamily(String npi) {
        String npiToReturn="";
        try (
        Connection con = ((DataSource) AppUtil.getApplicationContext().getBean("setupDataSource")).getConnection();
        PreparedStatement stmtSelectFolders = con.prepareStatement("select ind.c_numero_npi as pmtInd,pmt.c_npi_preinscription,ind.id as indId,ind.c_hl3 as seniorite,men.id as menId,pmt.id as pmtID from"
