            try (ResultSet rs1 = stmtSelectFolders.executeQuery()) {
                while (rs1.next()) {
                    npiToReturn = rs1.getString("pmtInd");
                    updateStatusPmt(rs1.getString("pmtID"));
                    return npiToReturn;
                }
                return npiToReturn;
            }
        }
    } catch (Exception e) {
        LogUtil.error("verifying NPI and enquete for reclassement ", e, "error");
        return npiToReturn;
    }

    }


    public void updateTableIndividus(String npi) {
        try (
        Connection con = ((DataSource) AppUtil.getApplicationContext().getBean("setupDataSource")).getConnection();
        PreparedStatement stmtSelectFolders = con.prepareStatement("update app_fd_table_individus set c_hl3='1' where c_numero_npi=?;")
    ) {
        if (!con.isClosed()) {
            stmtSelectFolders.setString(1,npi);
            stmtSelectFolders.executeUpdate();
        }
    } catch (Exception e) {
        LogUtil.error("updating chef de menage for desinscription ", e, "error");
    }

    }

    public void DeleteFromTableIndividus(String npi) {
        try (
        Connection con = ((DataSource) AppUtil.getApplicationContext().getBean("setupDataSource")).getConnection();
        PreparedStatement stmtSelectFolders = con.prepareStatement("delete from app_fd_table_individus where c_numero_npi=? and id!='';")
    ) {
        if (!con.isClosed()) {
            stmtSelectFolders.setString(1,npi);
            stmtSelectFolders.executeUpdate();
        }
    } catch (Exception e) {
        LogUtil.error("deleting from table individus for desinscription ", e, "error");
    }

    }

    public void updateStatusPmt(String pmtID) {
        try (
        Connection con = ((DataSource) AppUtil.getApplicationContext().getBean("setupDataSource")).getConnection();
        PreparedStatement stmtSelectFolders = con.prepareStatement("update app_fd_pmt set c_status='A valider' where id=?;")
    ) {
        if (!con.isClosed()) {
            stmtSelectFolders.setString(1,pmtID);
            stmtSelectFolders.executeUpdate();
        }
    } catch (Exception e) {
        LogUtil.error("updating status pmt for desinscription ", e, "error");
    }

    }
